'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/iconbutton/md-gb-icon-button.js';
import {IconButtonElement} from '@material/web/labs/gb/components/iconbutton/icon-button-element.js';

/**
 * A Material Design component. Wraps <md-gb-icon-button>.
 * Docs: https://material-web.dev/3.0/components/icon-button/
 */
export const MdIconButton = createComponent({
  react: React,
  tagName: 'md-gb-icon-button',
  elementClass: IconButtonElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdIconButtonProps = React.ComponentProps<typeof MdIconButton>;
